statement.tex:
次の極限を求めよ．
\begin{enumerate}
  \item $\displaystyle\lim_{x\to-\infty}\bigl(\sqrt{x^2+2x}+x\bigr)$
  \item $\displaystyle\lim_{x\to0}\frac{\sqrt{1+x}-1-\frac x2}{x^2}$
  \item $\displaystyle\lim_{x\to\infty}x\bigl(\sqrt{x^2+1}-x\bigr)$
\end{enumerate}

\begin{enumerate}
  \item $\displaystyle\lim_{n\to\infty}(2^n+3^n)^{\frac1n}$ を求めよ．
  \item 実数 $r$ に対し $\displaystyle\lim_{n\to\infty}\frac{r^n}{1+r^n}$ を調べよ（$r\neq-1$ のとき値を求め，$r=-1$ のときは理由を述べよ）．
\end{enumerate}

次の極限を求めよ．
\begin{enumerate}
  \item $\displaystyle\lim_{x\to0}\frac{\tan3x}{\sin5x}$
  \item $\displaystyle\lim_{x\to0}\frac{\sin(x^2)}{1-\cos x}$
  \item $\displaystyle\lim_{x\to0}\frac{\tan x-\sin x}{x^3}$
\end{enumerate}

次の極限を求めよ．
\begin{enumerate}
  \item $\displaystyle\lim_{x\to\frac\pi2}\frac{\cos x}{x-\frac\pi2}$
  \item $\displaystyle\lim_{x\to\infty}x\sin\frac1x$
  \item $\displaystyle\lim_{x\to1}\frac{\sin\pi x}{x-1}$
\end{enumerate}

\begin{enumerate}
  \item $\displaystyle\lim_{x\to0}\frac{2^x-1}{x}$ を求めよ．
  \item $\displaystyle\lim_{x\to0}\frac{\sqrt{4+x}-2}{x}$ を求めよ．
  \item 微分可能な $f(x)$ について，$\displaystyle\lim_{h\to0}\frac{\{f(a+h)\}^2-\{f(a)\}^2}{h}$ を $f(a),f'(a)$ で表せ．
\end{enumerate}

\begin{enumerate}
  \item $\displaystyle\lim_{x\to2}\frac{\sqrt{x+a}-b}{x-2}=\frac14$ となる定数 $a,b$ を求めよ．
  \item $\displaystyle\lim_{x\to\infty}\bigl(\sqrt{4x^2+x}-ax-b\bigr)=0$ となる定数 $a,b$ を求めよ．
\end{enumerate}

$a_1=\sqrt2,\ a_{n+1}=\sqrt{2+a_n}$ で定められる数列について，
\begin{enumerate}
  \item $a_n=2\cos\dfrac{\pi}{2^{n+1}}$ を示せ．
  \item $\displaystyle\lim_{n\to\infty}4^n(2-a_n)$ を求めよ．
\end{enumerate}

$a_1=2,\ a_{n+1}=\dfrac12\Bigl(a_n+\dfrac3{a_n}\Bigr)$ で定められる数列について，
\begin{enumerate}
  \item $a_n\geqq\sqrt3$ を示せ．
  \item $a_{n+1}-\sqrt3\leqq\dfrac12(a_n-\sqrt3)$ を示し，$\displaystyle\lim_{n\to\infty}a_n$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $\displaystyle\sum_{k=1}^\infty\frac{1}{k(k+2)}$ を求めよ．
  \item 無限級数 $1-1+\frac12-\frac12+\frac13-\frac13+\cdots$ の収束・発散を調べ，収束するなら和を求めよ．
  \item $\displaystyle\sum_{k=1}^\infty\frac1{\sqrt k}$ は発散することを示せ．
\end{enumerate}

\begin{enumerate}
  \item 無限級数 $x+\dfrac{x}{1+x^2}+\dfrac{x}{(1+x^2)^2}+\cdots$ はすべての実数 $x$ で収束することを示し，和 $f(x)$ を求めよ．$f(x)$ は $x=0$ で連続か．
  \item $\displaystyle\sum_{n=1}^\infty\frac{n}{2^n}$ と $\displaystyle\sum_{n=1}^\infty\frac{n^2}{2^n}$ を求めよ．
\end{enumerate}

$a_1=1$，$a_{n+1}=(3a_n$ を7で割った余り$)$ で数列 $\{a_n\}$ を定める．
\begin{enumerate}
  \item $a_1,\dots,a_7$ を求め，周期を答えよ．
  \item $\displaystyle\sum_{n=1}^\infty\frac{a_n}{2^n}$ を求めよ．
\end{enumerate}

1辺の長さ1の正三角形 $F_0$ から始め，$F_{n-1}$ の各辺を3等分して中央の部分を1辺とする正三角形を外側に付け加え（その中央の部分は取り除く），図形 $F_n$ をつくる（コッホ雪片）．
\begin{enumerate}
  \item $F_n$ の周の長さを求め，$n\to\infty$ で発散することを示せ．
  \item $F_n$ の面積の極限を求めよ．
\end{enumerate}

次の極限を求めよ．
\begin{enumerate}
  \item $\displaystyle\lim_{n\to\infty}\frac1n\sum_{k=1}^n\sin\frac{k\pi}{n}$
  \item $\displaystyle\lim_{n\to\infty}\sum_{k=1}^n\frac{n}{n^2+k^2}$
\end{enumerate}

\begin{enumerate}
  \item $x\geqq0$ のとき $1-\dfrac{x^2}2+\dfrac{x^4}{24}-\dfrac{x^6}{720}\leqq\cos x\leqq1-\dfrac{x^2}2+\dfrac{x^4}{24}$ を示せ．
  \item 定数 $k$ に対し $\displaystyle L(k)=\lim_{x\to+0}\Bigl(\frac1{1-\cos x}-\frac2{x^2+kx^4}\Bigr)$ を求めよ．
  \item $L(k)=0$ となる $k$ の値を求めよ．
\end{enumerate}

$k$ を実数の定数とする．
\begin{enumerate}
  \item 方程式 $\sqrt{2x-1}=x+k$ の実数解の個数を，$k$ の値で分類して答えよ．
  \item 不等式 $\sqrt{2x-1}>x+k$ の解が，長さ $2$ の区間となるような $k$ の値をすべて求めよ．
\end{enumerate}

$f(x)=\dfrac{4x-2}{x+1}$ とする．
\begin{enumerate}
  \item 定数 $\alpha<\beta$ と $k$ を，$g(x)=\dfrac{x-\alpha}{x-\beta}$ が $g(f(x))=k\,g(x)$ を恒等的に満たすように定めよ．
  \item 数列 $\{x_n\}$ を $x_1=0$，$x_{n+1}=f(x_n)$ で定めるとき，$x_n$ を $n$ で表し，$\displaystyle\lim_{n\to\infty}x_n$ を求めよ．
\end{enumerate}

$c$ を定数とし，$f(x)=x^2+c\ (x\geqq0)$ の逆関数を $g(x)$ とする．
\begin{enumerate}
  \item $g(x)$ とその定義域を求めよ．
  \item $c=\frac12$ のとき，曲線 $y=f(x)$ 上の点と曲線 $y=g(x)$ 上の点の距離の最小値を求めよ．
  \item 曲線 $y=f(x)$ と $y=g(x)$ が共有点をもつような $c$ の値の範囲を求めよ．
\end{enumerate}

$f_1(x)=2x^2-1$，$f_{n+1}(x)=2\{f_n(x)\}^2-1$ で関数 $f_n(x)$ を定める．
\begin{enumerate}
  \item 実数 $a$ に対し，$f_1(x)=a$ を満たす実数 $x$ の個数を求めよ．
  \item 実数 $a$ に対し，$f_2(x)=a$ を満たす実数 $x$ の個数を求めよ．
  \item $f_3(x)=0$ を満たす実数 $x$ をすべて求めよ．
\end{enumerate}

数列 $\{a_n\}$ について $S_n=\sum_{k=1}^na_k$，$S_0=0$ とおく．$a_n=S_{n-1}+3^n\ (n=1,2,\cdots)$ が成り立つとき，
\begin{enumerate}
  \item $S_n$ と $a_n$ を $n$ の式で表せ．
  \item $\displaystyle\lim_{n\to\infty}\frac{a_n}{S_n}$ を求めよ．
\end{enumerate}

$a_1=3$，$a_{n+1}=\dfrac{a_n^2+2}{2a_n}$ で定義される数列 $\{a_n\}$ について，
\begin{enumerate}
  \item すべての $n$ について $a_n>\sqrt2$ を示せ．
  \item $a_{n+1}-\sqrt2<\dfrac12(a_n-\sqrt2)$ を示し，$\displaystyle\lim_{n\to\infty}a_n$ を求めよ．
  \item $a_{n+1}-\sqrt2<\dfrac{(a_n-\sqrt2)^2}{2\sqrt2}$ を示せ．
\end{enumerate}

$r$ を実数とする．$a_1=0$，$a_2=1$，$3a_n=(r+2)a_{n-1}-(r-1)a_{n-2}\ (n\geqq3)$ で定まる数列 $\{a_n\}$ について，
\begin{enumerate}
  \item $b_n=a_{n+1}-a_n$ とおくとき，$b_n$ を $n$ と $r$ で表せ．
  \item 数列 $\{a_n\}$ が収束するような $r$ の範囲と，そのときの極限値を求めよ．
\end{enumerate}

$f(x)=-\dfrac13x+4$ とする．$x_1=0$ とおいて数列 $x_n=f(x_{n-1})\ (n=2,3,\cdots)$ をつくり，平面上に点 P$_n(x_n,f(x_n))$ をとる．
\begin{enumerate}
  \item 数列 $\{x_n\}$ の一般項を求めよ．
  \item 動点 P が P$_1$ を出発して P$_2$，P$_3$，$\cdots$ と線分で進むとき，P はどのような点に近づくか．
  \item 線分 P$_n$P$_{n+1}$ の長さを $l_n$ とするとき，$L=\displaystyle\sum_{n=1}^\infty l_n$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $h>0$，$n\geqq3$ のとき $(1+h)^n\geqq\dfrac{n(n-1)(n-2)}6h^3$ を示せ．
  \item $0<x<1$ のとき，数列 $\{n^2x^n\}$ は0に収束することを示せ．
  \item 無限級数 $\displaystyle\sum_{k=1}^\infty\frac{k^2}{2^k}$ の和を求めよ．
\end{enumerate}

$f(x)=x^3-3$，$c=\sqrt[3]3$ とし，$a_1=2$，$a_{n+1}=a_n-\dfrac{f(a_n)}{f'(a_n)}$ で数列を定める．
\begin{enumerate}
  \item すべての自然数 $n$ に対して $c<a_{n+1}<a_n$ を示せ．
  \item $a_{n+1}-c<\dfrac{(a_n-c)^2}{c}$ を示せ．
  \item $|a_n-c|<\dfrac1{1000}$ となる最小の $n$ を求めよ（$1.442^3<3<1.4425^3$ を用いてよい）．
\end{enumerate}

$0\leqq x<1$ で $f(x)=2x\ (x<\frac12)$，$2x-1\ (x\geqq\frac12)$ と定め，$f_1=f$，$f_n(x)=f(f_{n-1}(x))$ とする．
\begin{enumerate}
  \item $f_3(x)$ を式で表せ．
  \item $p=\dfrac17$，$\dfrac37$ のそれぞれについて $\displaystyle\lim_{n\to\infty}\frac{f_1(p)+\cdots+f_n(p)}n$ を求めよ．
  \item 2以上の自然数 $m$ に対し $p=\dfrac1{2^m-1}$ のとき，上の極限を $m$ で表せ．
\end{enumerate}

$a>0$ とし，$F(x)=\dfrac{x}{a+x}$，$f_1(x)=F(x)$，$f_{n+1}(x)=F(f_n(x))$ と定める．
\begin{enumerate}
  \item $x>0$ のとき $f_n(x)$ を $a,x,n$ の式で表せ．
  \item 「$c>0$ ならば数列 $\{b_n f_n(c)\}$ は正の数に収束する」という条件をみたす数列 $\{b_n\}$ を，$a<1$，$a=1$，$a>1$ の各場合に1つずつ作れ．
\end{enumerate}

$a$ を正の定数とし，$x_1=0$，$x_{n+1}=\sqrt{a+2x_n}$ で数列を定める．
\begin{enumerate}
  \item 数列が収束すると仮定して，その極限値 $\alpha$ を求めよ．
  \item $|x_{n+1}-\alpha|\leqq\dfrac2\alpha|x_n-\alpha|$ を示し，数列が実際に $\alpha$ に収束することを証明せよ．
\end{enumerate}

$a_1=c$，$a_{n+1}=\dfrac{a_n^2-1}{n+1}\ (n\geqq1)$ で数列を定める．
\begin{enumerate}
  \item $c=3$ のとき，一般項 $a_n$ を求めよ．
  \item $c>3$ ならば $\displaystyle\lim_{n\to\infty}a_n=\infty$ を示せ．
  \item $c=\sqrt2$ のとき，$\displaystyle\lim_{n\to\infty}a_n$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $a,b$ を実数とする．$\displaystyle\lim_{x\to\infty}\log_x(x^a+x^b)$ を求めよ．
  \item $a,b$ は $a^2+b^2\leqq1$ をみたす実数とする．$L=\displaystyle\lim_{x\to\infty}\log_x(3x^a+x^{2b})$ を最小にする $a,b$ と，そのときの $L$ を求めよ．
\end{enumerate}

次の極限を求めよ．
\begin{enumerate}
  \item $\displaystyle\lim_{x\to\sqrt3+0}\frac{x^2-3}{|x^2-(\sqrt3+1)x+\sqrt3|}$ と $\displaystyle\lim_{x\to\sqrt3-0}\frac{x^2-3}{|x^2-(\sqrt3+1)x+\sqrt3|}$
  \item $\displaystyle\lim_{x\to\infty}\left(\sqrt{x^2+4x+1}-x\right)$
  \item $f(x)=\dfrac1{\sqrt{x^2+2x}+x}$ のとき，$\displaystyle\lim_{x\to\infty}f(x)$，$\displaystyle\lim_{x\to-\infty}f(x)$
\end{enumerate}

次の極限を求めよ．
\begin{enumerate}
  \item $\displaystyle\lim_{n\to\infty}\frac{3^{2n+1}+2^n}{9^n+3^{n+1}}$
  \item $0<\theta<\frac\pi2$ のとき $\displaystyle\lim_{n\to\infty}\frac{\sin^n\theta-\cos^n\theta}{\sin^n\theta+\cos^n\theta}$（$\theta$ の値で場合分けせよ）
  \item $0\leqq a\leqq b\leqq c$，$c>0$ のとき $\displaystyle\lim_{n\to\infty}(a^n+b^n+c^n)^{\frac1n}$
\end{enumerate}

次の極限を求めよ．
\begin{enumerate}
  \item $\displaystyle\lim_{n\to\infty}n\tan\frac\pi{2n}$
  \item $\displaystyle\lim_{x\to0}\frac{\cos3x-\cos5x}{x^2}$
  \item $\displaystyle\lim_{n\to\infty}\frac{\sqrt{n^4+n^2+4}\left(1-\cos\frac3n\right)}{(n+1)\sin\frac2n}$
\end{enumerate}

次の極限を求めよ．
\begin{enumerate}
  \item $\displaystyle\lim_{x\to0}\frac{\sin2x}{e^{3x}-1}$
  \item $\displaystyle\lim_{x\to0}\frac{e^{x^2}-\cos x}{x^2}$
  \item $\displaystyle\lim_{x\to e}\frac{\log x-1}{x-e}$
\end{enumerate}

次の極限を求めよ．
\begin{enumerate}
  \item $\displaystyle\lim_{h\to0}(1+3h)^{\frac2h}$
  \item $\displaystyle\lim_{x\to\infty}\left(1-\frac2x+\frac5{x^2}\right)^{3x}$
\end{enumerate}

\begin{enumerate}
  \item 定数 $a,b$ に対して，等式 $\displaystyle\lim_{x\to\pi}\frac{ax+b}{\sin x}=2$ が成り立つとき，$a,b$ の値を求めよ．
  \item 等式 $\displaystyle\lim_{x\to\infty}\left(3x-\sqrt{ax^2-bx+2}\right)=1$ が成り立つように，定数 $a,b$ の値を求めよ．
\end{enumerate}

関数 $f(x)$ は $x=0$ で微分可能で $f'(0)=2$ とする．このとき，次の極限値を求めよ．
\begin{enumerate}
  \item $\displaystyle\lim_{x\to0}\frac{f(2x)-f(-3x)}x$
  \item $\displaystyle\lim_{x\to0}\frac{f(\sin x)-f(0)}{e^x-1}$
\end{enumerate}

次の各数列 $\{a_n\}$ について，極限 $\displaystyle\lim_{n\to\infty}\frac{a_2+a_4+\cdots+a_{2n}}{a_1+a_2+\cdots+a_n}$ を調べよ．
\begin{enumerate}
  \item $a_n=cr^n$（$c>0,\ r>0$）
  \item $a_n=\dfrac1{n(n+1)}$（$\displaystyle\sum_{k=1}^\infty\frac{(-1)^{k-1}}k=\log2$ は用いてよい）
\end{enumerate}

次の極限を求めよ．
\begin{enumerate}
  \item $\displaystyle\lim_{n\to\infty}\frac1n\sum_{k=1}^n\cos\frac{\pi k}{2n}$
  \item $\displaystyle\lim_{n\to\infty}\sum_{k=1}^n\frac n{n^2+k^2}$
  \item $\displaystyle\lim_{n\to\infty}\sum_{k=1}^n\frac1{\sqrt{n^2+2nk}}$
\end{enumerate}

数列 $\{a_n\}$ は $a_1=\sqrt2$，$a_{n+1}=\sqrt{2-a_n}$（$n=1,2,\dots$）によって定義されている．
\begin{enumerate}
  \item $0<a_n<2$ が成り立つことを示しなさい．
  \item $2\cos b_n=a_n$，$0<b_n<\frac\pi2$ を満たす $b_n$ について $b_{n+1}$ を $b_n$ で表し，$b_n$ を求めなさい．
  \item $\displaystyle\lim_{n\to\infty}a_n$ の値を求めなさい．
\end{enumerate}

数列 $\{a_n\}$ を $a_1=c$，$a_{n+1}=\sqrt{6a_n-a_n^2}$（$n=1,2,3,\dots$）で与える．ただし $c$ は $0<c<3$ を満たす定数である．
\begin{enumerate}
  \item $a_n<3$，$a_n<a_{n+1}$（$n=1,2,3,\dots$）を示せ．
  \item $3-a_{n+1}\leqq\dfrac{3-c}3(3-a_n)$（$n=1,2,3,\dots$）を示せ．
  \item $\displaystyle\lim_{n\to\infty}a_n$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $p$ を2以上の自然数とする．すべての正数 $x$ に対して $1+\dfrac1px-\dfrac{p-1}{2p^2}x^2<(1+x)^{\frac1p}<1+\dfrac1px$ が成り立つことを示せ．
  \item $\displaystyle\lim_{n\to\infty}\left\{(n^4+n^3)^{\frac14}-(n^3+n^2)^{\frac13}\right\}$ を求めよ．
\end{enumerate}

多角形の各辺に対し次の操作 (イ) を施す：辺 AB を3等分する内点 C，D をこの順にとり，CD を1辺とする正方形 CDFE を多角形の外側に作り，折れ線 A-C-E-F-D-B で辺 AB をおきかえる．1辺の長さが1の正方形 $T_0$ の各辺に操作 (イ) を施してできる多角形を $T_1$，以下同様に $T_n$ から $T_{n+1}$ を作る（図形どうしは重ならないものとする）．
\begin{enumerate}
  \item 多角形 $T_n$ の辺の個数 $a_n$ と1辺の長さ $l_n$ を $n$ で表せ．
  \item 多角形 $T_n$ の面積 $S_n$ を $n$ で表し，$n\to\infty$ のときの極限を調べよ．
  \item 多角形 $T_n$ の周の長さ $L_n$ を $n$ で表し，$n\to\infty$ のときの極限を調べよ．
\end{enumerate}

数列 $\{a_n\}$，$\{b_n\}$ を
\[
a_n=\frac11+\frac12-\frac23+\frac14+\frac15-\frac26+\cdots+\frac1{3n-2}+\frac1{3n-1}-\frac2{3n},\qquad b_n=\sum_{j=1}^{2n}\frac1{n+j}
\]
により定める．
\begin{enumerate}
  \item $a_1,b_1$ を求めよ．
  \item $a_n=b_n$（$n=1,2,3,\dots$）を示せ．
  \item $\displaystyle\lim_{n\to\infty}a_n$ を求めよ．
\end{enumerate}

$a$ は正の定数とする．数列 $\{x_n\}$ を $x_1=\sqrt a$，$x_{n+1}=\sqrt{a+2x_n}$（$n=1,2,3,\dots$）で定める．
\begin{enumerate}
  \item 数列 $\{x_n\}$ が収束すると仮定して，その極限値 $\alpha$ を求めよ．
  \item 数列 $\{x_n\}$ が実際に $\alpha$ に収束することを証明せよ．
\end{enumerate}

$\log x$ は $x$ の自然対数とする．
\begin{enumerate}
  \item $x>0$ のとき $\log x\leqq x-1$ を示し，$x>1$ のとき $\log x<2\sqrt x$ を示せ．
  \item $\displaystyle\lim_{x\to\infty}\frac{(\log x)^2}x$ を求めよ．
  \item $s>0$ のとき，$\displaystyle\lim_{x\to+0}x^s\log x$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 自然数 $n$ に対して，$n\log n-n+1\leqq\log(n!)\leqq(n+1)\log(n+1)-n$ を証明しなさい．
  \item $\displaystyle\lim_{n\to\infty}\frac{\log(n!)}{n\log n}$ を求めなさい．
  \item $\displaystyle\lim_{n\to\infty}\frac{\sqrt[n]{n!}}n$ を求めなさい．
\end{enumerate}

実数 $x$ に対し，$[x]$ は $x$ 以下の最大の整数を表す．$S(n)=\displaystyle\sum_{k=1}^n[\sqrt k]$ とする．
\begin{enumerate}
  \item $k,t$ を自然数とするとき，$[\sqrt k]=t$ となるような $k$ の範囲を $t$ を用いた不等式で表せ．
  \item 自然数 $m\geqq2$ に対して $S(m^2-1)$ を $m$ で表せ．
  \item $\displaystyle\lim_{n\to\infty}\frac{S(n)}{n\sqrt n}$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $x>0$ のとき，$x-\dfrac{x^2}2<\log(1+x)<x-\dfrac{x^2}2+\dfrac{x^3}3$ を示せ．
  \item 不等式 $\log(n+4)-\log(n+1)<\dfrac1{40}$ をみたす最小の正の整数 $n$ を求めよ．ただし，対数は自然対数とする．
\end{enumerate}

$p$ は正の偶数，$n$ は自然数とする．座標平面において，曲線 $y=\dfrac13x^p$ と2直線 $y=0$，$x=3n$ で囲まれた部分（境界も含む）に含まれている格子点の個数を $L_p(n)$ とする．
\begin{enumerate}
  \item $L_p(n)=1+\dfrac73n+\dfrac13\displaystyle\sum_{k=1}^{3n}k^p$ であることを示せ．
  \item 極限値 $\displaystyle\lim_{n\to\infty}\frac{L_p(n)}{n^{p+1}}$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $\displaystyle\lim_{n\to\infty}\sum_{k=1}^{2n}\frac1{n+k}$ を求めよ．
  \item 半径1の円に内接する正 $n$ 角形（$n\geqq3$）の異なる2つの頂点を結ぶ線分（辺と対角線）すべてについて，長さの2乗の総和は $n^2$ であることを示せ．
  \item (2) の線分すべての長さの総和を $L_n$ とするとき，$\displaystyle\lim_{n\to\infty}\frac{L_n}{n^2}$ を求めよ．
\end{enumerate}

1から $n$ までの数字が1つずつ書かれた $n$ 枚のカードがある．その中から3枚をとり，それを3辺の長さにもつ鋭角三角形が存在する場合の数を $b_n$ とする．
\begin{enumerate}
  \item $n=7$ のとき，1番大きな数が7となる場合は何通りか．また $b_7$ を求めよ．
  \item $0<x<y<1$ かつ $x^2+y^2>1$ をみたす点 $(x,y)$ 全体の面積を求めよ．
  \item $\displaystyle\lim_{n\to\infty}\frac{b_n}{n^3}$ を求めよ．
\end{enumerate}

$n$ 個のボールを $N$ 個の箱へ投げ入れる．各ボールはいずれかの箱に入るものとし，どの箱に入る確率も等しいとする．どの箱にも1個以下のボールしか入っていない確率を考える．
\begin{enumerate}
  \item $0\leqq x\leqq\frac12$ のとき $-x-x^2\leqq\log(1-x)\leqq-x$ を示せ．
  \item $N=n^2$ のときの確率を $p_n$ とする．$\displaystyle\lim_{n\to\infty}p_n$ を求めよ．
  \item $N=3n$ のときの確率を $q_n$ とする．$\displaystyle\lim_{n\to\infty}\frac{\log q_n}n$ を求めよ．
\end{enumerate}

$x\geqq0$ で定義された関数 $f_n(x)=x^a-x^{a+\frac1n}$ を考える．ただし，$a$ は正の実数とし，$n$ は自然数とする．
\begin{enumerate}
  \item 区間 $[0,1]$ において，$f_n(x)$ の最大値を与える $x$ の値を $x_n$ とおく．$x_n$ を求めよ．
  \item 極限 $\displaystyle\lim_{n\to\infty}x_n$ を求めよ．
  \item 極限 $\displaystyle\lim_{n\to\infty}nf_n(x_n)$ を求めよ．
\end{enumerate}

$a,b,t$ は実数で，$a\geqq0>b$ とする．次の漸化式により，数列 $a_n,b_n$（$n=1,2,\dots$）を定める．
\begin{align*}
&a_1=a,\quad b_1=b,\\
&a_{n+1}=\left(\frac t2+\frac{3t}{t^2+1}\right)a_n+\left(\frac t2-\frac{3t}{t^2+1}\right)b_n,\\
&b_{n+1}=\left(\frac t2-\frac{3t}{t^2+1}\right)a_n+\left(\frac t2+\frac{3t}{t^2+1}\right)b_n
\end{align*}
\begin{enumerate}
  \item $a_n$ を $a,b,t,n$ を用いて表せ．
  \item $n\to\infty$ とするとき，$a_n$ が収束するための $a,b,t$ についての必要十分条件を求めよ．
\end{enumerate}

平面上に半径1の円 $C$ がある．この円に外接し，さらに隣り合う2つが互いに外接するように，同じ大きさの $n$ 個の円を配置し，その一つの円の半径を $R_n$ とする．また，円 $C$ に内接し，さらに隣り合う2つが互いに外接するように，同じ大きさの $n$ 個の円を配置し，その一つの円の半径を $r_n$ とする．ただし，$n\geqq3$ とする．
\begin{enumerate}
  \item $R_4$，$r_4$ を求めよ．
  \item $\displaystyle\lim_{n\to\infty}nR_n$ を求めよ．
  \item $\displaystyle\lim_{n\to\infty}\left(\frac{R_n}{r_n}\right)^n$ を求めよ．
\end{enumerate}

$\theta=\dfrac\pi4$ とする．
\begin{enumerate}
  \item $a_n=\displaystyle\prod_{k=1}^n\cos\frac\theta{2^k}$ とするとき，$\displaystyle\lim_{n\to\infty}a_n$ を求めよ．
  \item $\tan x=\dfrac1{\tan x}-\dfrac2{\tan2x}$ を示せ．
  \item $\displaystyle\sum_{k=1}^\infty\frac1{2^k}\tan\frac\theta{2^k}$ を求めよ．
\end{enumerate}

数列 $\{a_n\}$ の初項から第 $n$ 項までの和 $S_n$ が $S_n=4-\dfrac{n+2}na_n$（$n=1,2,3,\dots$）を満たしている．
\begin{enumerate}
  \item $a_1$ を求めよ．$n\geqq2$ のとき $\dfrac{a_n}n$ を $\dfrac{a_{n-1}}{n-1}$ で表し，$a_n$ と $\displaystyle\sum_{n=1}^\infty\frac{a_n}n$ を求めよ．
  \item $n\geqq3$ のとき $2^n>\dfrac{n(n-1)(n-2)}6$ を示し，$\displaystyle\lim_{n\to\infty}\frac{n^2}{2^n}=0$ を示せ．
  \item $\displaystyle\sum_{n=1}^\infty a_n$，$\displaystyle\sum_{n=1}^\infty na_n$ を求めよ．
\end{enumerate}

実数 $x$ に対して，$l\leqq x<l+1$ をみたす整数 $l$ を $[x]$ と表す．数列 $\{a_n\}$ を $a_n=\dfrac1{[\sqrt n]}$（$n=1,2,3,\dots$）で定義し，$S_n=\displaystyle\sum_{k=1}^na_k$ とおく．
\begin{enumerate}
  \item $S_3$，$S_8$ を求めよ．
  \item $S_{m^2-1}$（$m=2,3,4,\dots$）を $m$ の式で表せ．
  \item $\displaystyle\sum_{t=1}^m\frac1t\leqq1+\log m$ を示し，数列 $\left\{\dfrac{S_n}{\sqrt n}\right\}$ が収束することを示して，その極限値を求めよ．
\end{enumerate}

座標平面上に原点Oを中心とする半径1の円 $C$ がある．点A$(-2,0)$ を通る直線が $y>0$ の範囲にある点Pにおいて円 $C$ と接するとする．自然数 $n\geqq2$ に対して点Aを通る $(n-1)$ 本の直線で $\angle$OAP を $n$ 等分する．これらの直線を直線AOとなす角が小さいものから順に $l_1,\dots,l_{n-1}$ とし，直線 $l_k$ と円 $C$ の2つの交点のうち点Aに近い方を $\mathrm Q_k$，他方を $\mathrm R_k$ とする．
\begin{enumerate}
  \item $\angle$OAP を求め，$\mathrm{AR}_k-\mathrm{AQ}_k$ を $n$ と $k$ を用いて表せ．
  \item 極限値 $\displaystyle\lim_{n\to\infty}\frac1n\sum_{k=1}^{n-1}(\mathrm{AR}_k-\mathrm{AQ}_k)^2$ を求めよ．
\end{enumerate}

$n$ を正の整数とする．数列 $\{a_k\}$ を $a_1=\dfrac1{n(n+1)}$，$a_{k+1}=-\dfrac1{k+n+1}+\dfrac nk\displaystyle\sum_{i=1}^ka_i$（$k=1,2,3,\dots$）によって定める．
\begin{enumerate}
  \item $a_2$ および $a_3$ を求めよ．
  \item 一般項 $a_k$ を求めよ．
  \item $b_n=\displaystyle\sum_{k=1}^{2n}\sqrt{a_k}$ とおくとき，$\displaystyle\lim_{n\to\infty}b_n=\log3$ を示せ．
\end{enumerate}

$a_1=1$ とし，数列 $\{a_n\}$ を漸化式 $a_{n+1}=\dfrac{a_n}{1+a_n^2}$（$n=1,2,3,\dots$）によって定める．このとき，以下の問いに答えよ．各 $n$ に対し $b_n=\dfrac1{a_n}$ とおく．
\begin{enumerate}
  \item $b_{n+1}^2=b_n^2+2+\dfrac1{b_n^2}$ を示し，$b_n^2\geqq2n-1$ を示せ．
  \item $b_n^2\leqq2n-1+\displaystyle\sum_{k=1}^{n-1}\frac1{2k-1}$（$n\geqq2$）を示せ．
  \item $\displaystyle\lim_{n\to\infty}\sqrt n\,a_n$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $f,g$ が $[a,b]$ で連続，$(a,b)$ で微分可能で $g'(x)\neq0$ のとき，$\dfrac{f(b)-f(a)}{g(b)-g(a)}=\dfrac{f'(c)}{g'(c)}$ となる $c$（$a<c<b$）が存在することを示せ（コーシーの平均値の定理）．
  \item (1) を用いて，$f(a)=g(a)=0$ かつ $\displaystyle\lim_{x\to a+0}\frac{f'(x)}{g'(x)}=L$ ならば $\displaystyle\lim_{x\to a+0}\frac{f(x)}{g(x)}=L$ であることを示せ．
  \item $\displaystyle\lim_{x\to0}\frac{\tan x-x}{x^3}$ と $\displaystyle\lim_{x\to0}\frac{e^x-1-x-\frac{x^2}2}{x^3}$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $\displaystyle\sum_{n=1}^\infty\frac1{n(n+2)}$ を求めよ．
  \item $\displaystyle f(x)=\sum_{n=1}^\infty\frac{x^2}{(1+x^2)^n}$ を求め，$f(x)$ が $x=0$ で不連続であることを示せ．
  \item $\displaystyle\sum_{n=1}^\infty\frac{n^2}{3^n}$ を求めよ．
\end{enumerate}

$a$ を正の定数とし，$f(x)=\displaystyle\lim_{n\to\infty}\frac{x^{n+1}+(x^2-1)x\cos ax}{x^n+x^2-1}$ とする．
\begin{enumerate}
  \item $|x|<1$，$x=1$，$x=-1$，$|x|>1$ のそれぞれについて $f(x)$ を求めよ．
  \item $f(x)$ がすべての $x$ で連続となる最小の $a$ を求めよ．
  \item (2) のとき，方程式 $f(x)=0$ の実数解をすべて求めよ．
\end{enumerate}

定数 $a$（$1<a<3$）に対して $x_1=a$，$x_{n+1}=\sqrt{4x_n-3}$ で数列を定める．
\begin{enumerate}
  \item $a\leqq x_n<3$ を示せ．
  \item $0<3-x_{n+1}\leqq\dfrac4{3+\sqrt{4a-3}}(3-x_n)$ を示し，$\displaystyle\lim_{n\to\infty}x_n$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $x>0$ のとき $e^x>1+x+\dfrac{x^2}{2!}+\dots+\dfrac{x^n}{n!}$ を示し，$\displaystyle\lim_{x\to\infty}\frac{x^n}{e^x}=0$ を示せ．
  \item $\displaystyle\lim_{x\to\infty}\frac{(\log x)^3}{\sqrt x}$ を求めよ．
  \item $\displaystyle\lim_{x\to+0}x^x$ を求めよ．
\end{enumerate}

面積1の正三角形 $A_0$ から始めて，$A_{n-1}$ の各辺の中央の $\frac13$ を1辺とする正三角形を $A_{n-1}$ の内側から切り取ってできる図形を $A_n$ とする（切り取る三角形どうしは重ならないとしてよい）．
\begin{enumerate}
  \item $A_n$ の辺の数と周の長さの極限を求めよ（$A_0$ の1辺を $l$ とする）．
  \item $A_n$ の面積 $S_n$ を求め，$\displaystyle\lim_{n\to\infty}S_n$ を求めよ．
\end{enumerate}

1, 2, 2, 2, 3, 3, 3, 3, 3, 4, … は $k$ が $2k-1$ 個ずつ続く数列である．第 $n$ 項を $a_n$ とする．
\begin{enumerate}
  \item $(m-1)^2<n\leqq m^2$ のとき $a_n=m$ であることを示し，$\displaystyle\lim_{n\to\infty}\frac{a_n}{\sqrt n}$ を求めよ．
  \item $\displaystyle\lim_{n\to\infty}\frac1{n\sqrt n}\sum_{k=1}^na_k$ を求めよ．
\end{enumerate}

連続関数 $f(x)$ が $\displaystyle\lim_{x\to1}\frac{f(x)}{x^2-1}=a$，$\displaystyle\lim_{x\to2}\frac{f(x)}{x-2}=b$ をみたしている．
\begin{enumerate}
  \item $f(1)$，$f(2)$，$f'(1)$，$f'(2)$ を求めよ．
  \item $ab>0$ のとき，$1\leqq x\leqq2$ で $f(x)=0$ は少なくとも3個の解をもつことを示せ．
  \item $ab<0$ のとき，(2) の結論が成り立たない例をあげよ．
\end{enumerate}

平面上に3点 P$_0$，A，B がある．点 P$_0$ からAに向かって，Aまでの距離の $\frac12$ 進んで P$_1$ とし，P$_1$ からBに向かって，Bまでの距離の $\frac13$ 進んで P$_2$ とする．以下同様に，Aへ $\frac12$，Bへ $\frac13$ を交互に繰り返して P$_3$，P$_4$，…を定める．
\begin{enumerate}
  \item $\overrightarrow{\mathrm P_{2n+2}}$ を $\overrightarrow{\mathrm P_{2n}}$，$\vec a$，$\vec b$ で表せ（位置ベクトル）．
  \item $\displaystyle\lim_{n\to\infty}\mathrm P_{2n}$，$\displaystyle\lim_{n\to\infty}\mathrm P_{2n+1}$ はそれぞれ線分AB上のどの点か．
\end{enumerate}

山羊が囲いの外側で，囲いの周の半分の長さのひもで囲いの1つの角につながれている．山羊が動ける範囲（囲いの外側）の面積を求めよ．
\begin{enumerate}
  \item 囲いが1辺1の正方形のとき．
  \item 囲いが1辺1の正三角形のとき（ひもの長さ $\frac32$）．
  \item 囲いが半径 $R$ の円に内接する正 $2n$ 角形のときの面積 $S_{2n}$ を求め，$\displaystyle\lim_{n\to\infty}S_{2n}$ を求めよ（扇形どうしは重ならないとしてよい）．
\end{enumerate}

\begin{enumerate}
  \item $J_n=\displaystyle\int_0^{\frac\pi n}e^{-2x}\sin nx\,dx$ を求めよ．
  \item $\displaystyle\lim_{n\to\infty}\int_0^{n\pi}e^{-2x}|\sin nx|\,dx$ を求めよ．
\end{enumerate}

$a_n=\displaystyle\int_0^{\frac\pi3}e^{n\sin\theta}d\theta$，$b_n=\displaystyle\int_0^{\frac\pi3}e^{n\sin\theta}\cos\theta\,d\theta$（$n=1,2,\dots$）とする．
\begin{enumerate}
  \item $b_n$ を求めよ．
  \item $b_n\leqq a_n\leqq2b_n$ を示せ．
  \item $\displaystyle\lim_{n\to\infty}\frac1n\log(na_n)$ を求めよ．
\end{enumerate}

$a$ を3の倍数でない2以上の整数とする．方程式 $ax-3y=2$ をみたす自然数の組 $(x,y)$ について答えよ．
\begin{enumerate}
  \item 組 $(x,y)$ は無数に存在することを示せ．
  \item 組の列 $(x_1,y_1),(x_2,y_2),\dots$ が，「$n\geqq2$ について $x_n$ は $x_1,\dots,x_{n-1}$ のどれとも異なる」をみたすとき，$\displaystyle\lim_{n\to\infty}\frac1n\sum_{k=1}^n\frac{y_k}{x_k}$ を求めよ．
\end{enumerate}

数列 $\{a_n\}$ を $a_1=1$，$a_2=3$，$a_{n+2}=a_{n+1}+a_n$ で定める．$\theta_n$ を $0<\theta_n<\frac\pi2$，$\tan\theta_n=\dfrac{\sqrt5}{a_n}$ により定める．
\begin{enumerate}
  \item $a_na_{n+3}-a_{n+1}a_{n+2}=5(-1)^n$ を示せ．
  \item $\theta_{2k-1}=\theta_{2k}+\theta_{2k+1}$（$k=1,2,\dots$）を示せ．
  \item $\displaystyle\sum_{k=1}^\infty\theta_{2k}$ の値を $\tan$ の値で答えよ．
\end{enumerate}

次の極限を求めよ．
\begin{enumerate}
  \item $\displaystyle\lim_{n\to\infty}\left(n\cdot2^n+\frac{3^n}n\right)^{\frac1n}$
  \item $\displaystyle\lim_{n\to\infty}\left(\sum_{k=1}^nk^2\cdot2^k\right)^{\frac1n}$
\end{enumerate}

さいころを $n$ 回振り，出た目の積を $X_n$ とする．
\begin{enumerate}
  \item $X_n$ が4で割り切れる確率を求めよ．
  \item $X_n$ が12で割り切れる確率 $p_n$ を求めよ．
  \item $\displaystyle\lim_{n\to\infty}\frac1n\log(1-p_n)$ を求めよ．
\end{enumerate}

$a_1=0$，$b_1=10$，$a_{n+1}=\sqrt{3b_n+4}$，$b_{n+1}=\sqrt{3a_n+4}$ で数列を定める．
\begin{enumerate}
  \item $|a_{n+1}-4|\leqq\frac34|b_n-4|$，$|b_{n+1}-4|\leqq\frac34|a_n-4|$ を示せ．
  \item $\displaystyle\lim_{n\to\infty}a_n$，$\displaystyle\lim_{n\to\infty}b_n$ を求めよ．
\end{enumerate}

$x_1=0$，$x_{n+1}=\sqrt[3]{6+x_n}$ で数列を定める．
\begin{enumerate}
  \item $\{x_n\}$ が収束すると仮定して，極限値を求めよ．
  \item $|x_{n+1}-2|<\frac14|x_n-2|$ を示し，$\{x_n\}$ が (1) の値に収束することを証明せよ．
\end{enumerate}

$f(x)=2-x^2$ とする．
\begin{enumerate}
  \item $f(a)=a$ をみたす正の数 $a$ を求めよ．
  \item $x\geqq\frac12$ ならば $|f(x)-f(a)|\geqq\frac32|x-a|$ を示せ．
  \item $x_{n+1}=f(x_n)$ で定まる数列が，すべての $n$ で $\frac12\leqq x_n\leqq\frac32$ をみたすならば，$x_1=a$ であることを示せ．
\end{enumerate}

$S_n=\displaystyle\sum_{k=1}^n\frac{(-1)^{k+1}}{\sqrt k}$，$E_n=S_{2n}$，$O_n=S_{2n-1}$ とする．ただし，増加数列でつねにある定数以下であるもの，および減少数列でつねにある定数以上であるものは収束することを用いてよい．
\begin{enumerate}
  \item $\{E_n\}$ は増加，$\{O_n\}$ は減少であることを示せ．
  \item すべての $m,n$ で $E_m<O_n$ を示し，$\{E_n\}$，$\{O_n\}$ は同じ値 $S$ に収束することを示せ．
  \item $1-\frac1{\sqrt2}<S<1-\frac1{\sqrt2}+\frac1{\sqrt3}$ を示せ．
\end{enumerate}

複素数平面上で正三角形 P$_n$Q$_n$R$_n$ を次で定める．(A) P$_1$，Q$_1$，R$_1$ はそれぞれ $0$，$1$，$\frac12+\frac{\sqrt3}2i$．(B) P$_{n+1}=$R$_n$，Q$_{n+1}$ は線分R$_n$Q$_n$ を $1:2$ に内分する点，R$_{n+1}$ は三角形P$_n$Q$_n$R$_n$ の外部にある．
\begin{enumerate}
  \item R$_2$，R$_3$ を表す複素数 $z_2$，$z_3$ を求めよ．
  \item R$_n$ を表す複素数 $z_n$ を求めよ．
  \item $\displaystyle\lim_{n\to\infty}z_n$ を求めよ．
\end{enumerate}

正の整数 $n$ に対し，$0\leqq x\leqq\pi$ の範囲で $|\sin nx|\geqq\sin x$ をみたす $x$ の区間の長さの総和を $S_n$ とする．
\begin{enumerate}
  \item $c$ を $0\leqq c\leqq1$ の定数とし，$\sin\alpha=c$，$0\leqq\alpha\leqq\frac\pi2$ をみたす $\alpha$ をとる．$0\leqq\theta\leqq\pi$ で $|\sin\theta|\geqq c$ となる部分の長さを $\alpha$ で表せ．
  \item $\displaystyle\lim_{n\to\infty}S_n$ を求めよ．
\end{enumerate}

$0<r<\frac12$ とし，中心が原点で半径1と $1-2r$ の同心円に同時に接する半径 $r$ の円 $C_1$ と，$C_1$ を原点のまわりに $\frac{2\pi}n$ 回転した円 $C_2$（$n\geqq2$）を考える．条件「$C_1$ と $C_2$ は外接するか互いの外部にある」を考える．
\begin{enumerate}
  \item 条件は $\sin\frac\pi n\geqq\frac r{1-r}$ と同値であることを示せ．
  \item 条件をみたす最大の整数 $n$ を $N(r)$ とする．$N\left(\frac14\right)$ を求めよ．
  \item $\displaystyle\lim_{r\to+0}rN(r)$ を求めよ．
\end{enumerate}

$a_1=3$，$a_{n+1}=(\sqrt2)^{a_n}$ で数列を定め，$f(x)=(\sqrt2)^x$ とする．
\begin{enumerate}
  \item $2<x<4$ ならば $2<f(x)<x$ であることを示せ．
  \item $2\leqq x\leqq3$ で $0<f'(x)\leqq\sqrt2\log2$ を示し，$\sqrt2\log2<1$ を確かめよ．
  \item $0<a_{n+1}-2\leqq(\sqrt2\log2)(a_n-2)$ を示し，$\displaystyle\lim_{n\to\infty}a_n$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $\displaystyle\lim_{n\to\infty}\sqrt n\left(\sqrt{9n+3}-2\sqrt{4n+c}+\sqrt{n+4}\right)=1$ となる定数 $c$ を求めよ．
  \item $L_n=\sqrt{n^2+an+2}-2\sqrt{n^2+3n+1}+\sqrt{n^2-3n+2}$ とする．$\displaystyle\lim_{n\to\infty}L_n=0$ となる $a$ を求め，そのとき $\displaystyle\lim_{n\to\infty}nL_n$ を求めよ．
\end{enumerate}

$n$ は自然数，$[x]$ は $x$ を超えない最大の整数を表す．
\begin{enumerate}
  \item $\displaystyle\lim_{n\to\infty}\cos\left(2\pi\sqrt{n^2+\left[\frac n4\right]}\right)$ を求めよ．また，$\displaystyle\lim_{n\to\infty}\sin\left(\pi\sqrt{n^2+n+\left[\frac n3\right]}\right)$ は存在しないことを示せ．
  \item $a>0$，$b>0$ のとき，$\displaystyle\lim_{n\to\infty}\left(\frac{2a^{\frac1n}+b^{\frac1n}}3\right)^n$ を求めよ．
  \item $\displaystyle\lim_{n\to\infty}\left(\sum_{k=1}^nk^k\right)^{\frac1{n\log n}}$ を求めよ．
\end{enumerate}

曲線 $y=\sqrt{1+x^2}$ 上の2点 P，Q の $x$ 座標をそれぞれ $a-h$，$a+2h$（$h>0$）とし，直線 $x=a$ と線分PQ，曲線との交点をそれぞれ B，A とする．$l=\mathrm{AB}$ とおく．
\begin{enumerate}
  \item 2回微分可能な関数 $f$ について，$\displaystyle\lim_{h\to0}\frac1{h^2}\left\{\frac{2f(a-h)+f(a+2h)}3-f(a)\right\}=f''(a)$ を示せ（$f''$ は連続とする）．
  \item $\displaystyle\lim_{h\to+0}\frac l{h^2}$ を $a$ で表せ．
\end{enumerate}

正の整数 $n$ に対して $(2+\sqrt3)^n=x_n+y_n\sqrt3$ となる整数 $x_n,y_n$ を定める．
\begin{enumerate}
  \item $x_{n+1},y_{n+1}$ を $x_n,y_n$ で表し，$x_n^2-3y_n^2$ を求めよ．
  \item $0<\dfrac{x_n}{y_n}-\sqrt3=\dfrac1{y_n(x_n+\sqrt3y_n)}$ を示し，$\dfrac{x_{n+1}}{y_{n+1}}$ は $\dfrac{x_n}{y_n}$ よりも $\sqrt3$ のよい近似値であることを示せ．また $\displaystyle\lim_{n\to\infty}\frac{x_n}{y_n}$ を求めよ．
  \item $\left|\dfrac{x_n}{y_n}-\sqrt3\right|<10^{-6}$ となる最小の $n$ を求めよ．
\end{enumerate}

$f(x)=\dfrac1{x^2}-3$（$x>0$）とする．曲線 $y=f(x)$ 上の点 $(a_n,f(a_n))$ における接線が $x$ 軸と交わる点を $(a_{n+1},0)$ とし，$a_1=\frac12$ とする．$\alpha=\frac1{\sqrt3}$ とおく．
\begin{enumerate}
  \item $a_{n+1}$ を $a_n$ で表せ．
  \item $\frac12\leqq a_n<\alpha$ かつ $a_n<a_{n+1}$ を示し，$\displaystyle\lim_{n\to\infty}a_n$ を求めよ．
  \item $0<\alpha-a_{n+1}<\dfrac{3\sqrt3}2(\alpha-a_n)^2$ を示せ．
\end{enumerate}

数列 $\{a_n\}$ が $a_1=\sqrt2$，$a_{n+1}=\sqrt{2-a_n}$（$n=1,2,\dots$）で定められている．
\begin{enumerate}
  \item $a_n=2\cos\theta_n$，$0<\theta_n<\frac\pi2$ をみたす $\theta_n$ を求めよ．
  \item $\displaystyle\lim_{n\to\infty}a_n$ と $\displaystyle\lim_{n\to\infty}(-2)^{n-1}(a_n-1)$ を求めよ．
\end{enumerate}

$a>1$ とし，数列 $\{x_n\}$ を $x_1=a$，$x_{n+1}=x_n^2-x_n+1$ で定める．
\begin{enumerate}
  \item $\displaystyle\lim_{n\to\infty}x_n=\infty$ を示せ．
  \item 無限級数 $\displaystyle\sum_{n=1}^\infty\frac1{x_n}$ は収束することを示し，その和を求めよ．
  \item $a=2$ のとき，$\frac12+\frac13+\frac17+\frac1{43}+\dots$ の和を求めよ．
\end{enumerate}

solutions.tex:
$n^2<n^2+k^2\leqq2n^2$ より $n(2n^2)^{-\alpha}\leqq S_n\leqq n\cdot n^{-2\alpha}$，すなわち $2^{-\alpha}n^{1-2\alpha}\leqq S_n\leqq n^{1-2\alpha}$．
\begin{itemize}
  \item $0<\alpha<\frac12$：下からの評価で $S_n\to\infty$．\textbf{発散}．
  \item $\alpha>\frac12$：上からの評価で $S_n\to0$．\textbf{0 に収束}．
  \item $\alpha=\frac12$：$S_n=\frac1n\sum\frac1{\sqrt{1+(k/n)^2}}\to\int_0^1\frac{dx}{\sqrt{1+x^2}}=\left[\log(x+\sqrt{1+x^2})\right]_0^1$．\textbf{$\log(1+\sqrt2)$ に収束}．
\end{itemize}

statement.tex:
自然数 $n$ に対して $\displaystyle I_n=\int_0^\pi e^x|\sin nx|\,dx$ とする．
\begin{enumerate}
  \item $\displaystyle\int_{\frac{(k-1)\pi}n}^{\frac{k\pi}n}|\sin nx|\,dx$ を求めよ．
  \item $\displaystyle\lim_{n\to\infty}I_n$ を求めよ．
\end{enumerate}

次の極限値を求めよ．
\begin{enumerate}
  \item $\displaystyle L_1=\lim_{n\to\infty}\frac{(n+1)^a+(n+2)^a+\dots+(n+2n)^a}{1^a+2^a+\dots+n^a}$（$a>0$）
  \item $\displaystyle L_2=\lim_{n\to\infty}\left\{\frac{(3n)!}{n!\,n^{2n}}\right\}^{\frac1n}$
\end{enumerate}

$a$ は $0<a<\pi$ をみたす定数とする．$n=1,2,\dots$ に対し，$n\pi<x<(n+1)\pi$ の範囲に $\sin(x+a)=x^2\sin x$ をみたす $x$ がただ1つ存在することが知られている．その値を $x_n$ とする．
\begin{enumerate}
  \item $y_n=x_n-n\pi$ とおくとき，$\sin(y_n+a)=(n\pi+y_n)^2\sin y_n$ を示せ．
  \item $\displaystyle\lim_{n\to\infty}y_n=0$ を示せ．
  \item $\displaystyle\lim_{n\to\infty}n^2(x_n-n\pi)$ を求めよ．
\end{enumerate}

半径1の円 $D_0$ に内接し，互いに隣どうし外接する $k$ 個（$k\geqq3$）の半径の等しい円を描く．これら $k$ 個の円すべてに外接する円 $D_1$（中央の円）の中に同じ操作で $k$ 個の円を描き，これを無限に繰り返す．描かれる円の面積の総和を $S_k$，円周の長さの総和を $C_k$ とする．
\begin{enumerate}
  \item $k=4$ のとき，$S_4$ と $C_4$ を求めよ．
  \item 一般の $k$ に対して $S_k$，$C_k$ を求めよ．
  \item $\displaystyle\lim_{k\to\infty}S_k$ を求め，$D_0$ の面積に対する割合の極限を答えよ．
\end{enumerate}

$0<r<1$ とし，$b_n=\dfrac{n(n+1)}2$，$c_n=\displaystyle\sum_{k=1}^nb_k$ とする．
\begin{enumerate}
  \item $\displaystyle\lim_{n\to\infty}n^3r^n=0$ を証明せよ．
  \item $\displaystyle\sum_{n=1}^\infty n^2r^n$ を求めよ．
  \item $\displaystyle\sum_{n=1}^\infty b_nr^n$ と $\displaystyle\sum_{n=1}^\infty c_nr^n$ を求めよ．
\end{enumerate}

数列 $\{a_n\}$ を $a_1=1$，$a_{n+1}=\sqrt[3]{2a_n+1}$ で定める．
\begin{enumerate}
  \item $\alpha^3=2\alpha+1$ をみたす正の数 $\alpha$ を求めよ．
  \item すべての $n$ に対して $1\leqq a_n<\alpha$ であり，$\{a_n\}$ は増加することを示せ．
  \item $\alpha-a_{n+1}\leqq\dfrac{\alpha-a_n}{\alpha^2}$ を示し，$\displaystyle\lim_{n\to\infty}a_n$ を求めよ．
\end{enumerate}

実数 $x$ を超えない最大の整数を $[x]$ とし，$a_n=\dfrac n{[\sqrt[3]n]}$，$S_n=\displaystyle\sum_{k=1}^na_k$ とおく．
\begin{enumerate}
  \item $S_7$，$S_{26}$ を求めよ．
  \item $S_{m^3-1}$（$m=2,3,\dots$）を $m$ の式で表せ．
  \item $\displaystyle\lim_{n\to\infty}\frac{S_n}{n^{\frac53}}$ を求めよ．
\end{enumerate}

$n$ を自然数とする．$1,2,\dots,n$ の数字を書いた玉が1個ずつ入ったつぼから，1個取り出して数字を見てもとに戻す試行を $n$ 回行う．1の玉をちょうど $k$ 回取り出す確率を $p_k$ とする．
\begin{enumerate}
  \item $p_k$ を求めよ．
  \item 1の玉を偶数回（0回を含む）取り出す確率 $E_n$ を求め，$\displaystyle\lim_{n\to\infty}E_n$ を求めよ．
  \item 1の玉を取り出す回数が3の倍数（0を含む）である確率の，$n\to\infty$ での極限を求めよ．
\end{enumerate}

対数関数を用いずに，次を示せ．
\begin{enumerate}
  \item $a>1$，$n\geqq2$ のとき，$\sqrt[n]a=1+h_n$ とおくと $0<h_n<\dfrac{a-1}n$．
  \item $n\geqq2$ のとき $0<\sqrt[n]n-1<\sqrt{\dfrac2{n-1}}$．これから $\displaystyle\lim_{n\to\infty}\sqrt[n]n=1$ と $\displaystyle\lim_{n\to\infty}(n!)^{\frac1{n^2}}=1$．
  \item $\displaystyle\lim_{x\to+0}(\sin x)^x=1$．ただし，$\displaystyle\lim_{x\to+0}x^x=1$ は用いてよい．
\end{enumerate}

$n\geqq3$ とする．原点Oを中心とする半径1の円周を $n$ 等分する点 $\mathrm P_0,\mathrm P_1,\dots,\mathrm P_{n-1}$ をとり，$\mathrm P_n=\mathrm P_0$ とする．各 $i=1,\dots,n$ に対し，点 $\mathrm P_{i-1}$，$\mathrm P_i$ でそれぞれこの円に接し（円と共通の接線をもち），線分 $\mathrm P_{i-1}\mathrm P_i$ の垂直二等分線を軸とする放物線を $C_i$ とし，$C_i$ の $\mathrm P_{i-1}$ から $\mathrm P_i$ までの弧を $\gamma_i$ とする．弧 $\gamma_1,\dots,\gamma_n$ で囲まれる部分の面積を $S_n$ とする．
\begin{enumerate}
  \item $S_n$ を $n$ で表せ．
  \item $\displaystyle\lim_{n\to\infty}S_n$ を求めよ．
  \item $\displaystyle\lim_{n\to\infty}n^2(S_n-\pi)$ および $\displaystyle\lim_{n\to\infty}n^4(S_n-\pi)$ を求めよ．
\end{enumerate}

$a,b,c,d$ を正の定数とし，$f(x)=x^4+ax^3+bx^2+cx+d$ とする．
\begin{enumerate}
  \item 定数 $p,q,r$ に対し，$x\geqq1$ ならば $|px^2+qx+r|\leqq Rx^2$ となる定数 $R$ が存在することを示せ．
  \item $x\geqq1$ ならば $\left|\sqrt[4]{f(x)}-x-\dfrac a4\right|\leqq\dfrac lx$ となる定数 $l$ が存在することを示せ．
  \item すべての自然数 $n$ に対して $\sqrt[4]{f(n)}$ が自然数であるとする．このとき，自然数 $m$ を用いて $f(x)=(x+m)^4$ と表されることを示せ．
\end{enumerate}

$a_1=1$，$a_{n+1}=\dfrac{a_n}{1+a_n^{\,2}}$（$n=1,2,3,\cdots$）で数列 $\{a_n\}$ を定め，$b_n=\dfrac1{a_n^{\,2}}$ とおく．
\begin{enumerate}
  \item すべての $n$ について $a_n>0$ であることを示し，$b_{n+1}$ を $b_n$ で表せ．さらに $b_n\geqq2n-1$ を示せ．
  \item $b_n\leqq2n-1+2\sqrt{n-1}$ を示せ．
  \item $\displaystyle\lim_{n\to\infty}\sqrt n\,a_n$ を求めよ．
\end{enumerate}

実数 $a$，$b$，$c$ に対し
\[
P(x)=\sqrt[3]{x^3+ax^2+bx},\qquad Q(x)=\sqrt{x^2+cx}
\]
とおく（$\sqrt[3]{\ }$ は実数の3乗根）．
\begin{enumerate}
  \item $\displaystyle\lim_{x\to\infty}x^2\{P(x)-Q(x)\}=\frac16$ が成り立つような $a$，$b$，$c$ を求めよ．
  \item (1) で求めた $a$，$b$，$c$ に対して，$\displaystyle\lim_{x\to-\infty}x^2\{P(x)+Q(x)\}$ を求めよ．
\end{enumerate}

$0<r<1$ とする．$k=0,1,2,\dots$ に対し，点 O を中心とする半径 $r^k$ の円を $C_k$ とする．各 $k$ について，$C_k$ と $C_{k+1}$ にはさまれた部分に，$C_k$ に内接し $C_{k+1}$ に外接する円をできるだけたくさん描く．ただし，描いたどの2つの円も共有点は1個以下とする．こうして描いたすべての円（すべての $k$ にわたる）の円周の長さの総和を $F(r)$ とする．
\begin{enumerate}
  \item $\sin\theta=\dfrac{1-r}{1+r}$，$0<\theta<\dfrac\pi2$ をみたす角 $\theta$ をとる．$C_k$ と $C_{k+1}$ の間に描ける円の個数 $N$ は $k$ によらないことを示し，$N$ を $\theta$ を用いて表せ．また $F(r)$ を $N$ で表せ．
  \item $N=6$ となる $r$ の値の範囲を求めよ．
  \item $\displaystyle\lim_{r\to1-0}(1-r)F(r)$ を求めよ．
\end{enumerate}

$n$ を自然数とする．
\begin{enumerate}
  \item 方程式 $x\sin x=1$ は区間 $2n\pi<x<(2n+1)\pi$ にちょうど2つの解をもつことを示せ．それらを $\alpha_n<\beta_n$ とする．
  \item $\displaystyle\lim_{n\to\infty}n(\alpha_n-2n\pi)$ と $\displaystyle\lim_{n\to\infty}n\{(2n+1)\pi-\beta_n\}$ を求めよ．
  \item $\displaystyle\lim_{n\to\infty}n^2\bigl[\{(2n+1)\pi-\beta_n\}-(\alpha_n-2n\pi)\bigr]$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $\displaystyle\lim_{x\to\infty}\frac{x^2}{\log x}\left\{\frac{\log(x+1)}{x+1}-\frac{\log x}{x}\right\}$ を求めよ．
  \item $\displaystyle\lim_{x\to\infty}\left\{\frac{(x+1)^{\frac{1}{x+1}}}{x^{\frac1x}}\right\}^{\frac{x^2}{\log x}}$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 自然数 $n$ と $x>0$ に対して，$e^x>1+x+\dfrac{x^2}{2!}+\cdots+\dfrac{x^n}{n!}$ を示せ．
  \item $\displaystyle\lim_{x\to\infty}\frac{(\log x)^2}{x}=0$ および $\displaystyle\lim_{x\to+0}x(\log x)^2=0$ を示せ．
  \item $\displaystyle\lim_{x\to+0}\frac{x^x-1}{x\log x}$ を求めよ．
  \item $\displaystyle\lim_{x\to+0}\frac{x^{x^x-1}-1}{x(\log x)^2}$ を求めよ．ただし $x^{x^x-1}$ は $x^{(x^x-1)}$ を表す．
\end{enumerate}

$f(x)=x^{100}$ とする．
\begin{enumerate}
  \item $k$ が3の倍数のとき $\varepsilon_k=-2$，そうでないとき $\varepsilon_k=1$ とする．極限 $\displaystyle\lim_{n\to\infty}\sum_{k=1}^{3n}\varepsilon_kf\!\left(\frac k{3n}\right)$ を求めよ．
  \item $k$ を3で割った余りが2のとき $\delta_k=-2$，そうでないとき $\delta_k=1$ とする．極限 $\displaystyle\lim_{n\to\infty}n\sum_{k=1}^{3n}\delta_kf\!\left(\frac k{3n}\right)$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 関数 $f(x)$ は区間 $[0,1]$ で2回微分可能で，$f''(x)$ は連続とする．
  \[
  \lim_{n\to\infty}n^2\left\{\frac1n\sum_{k=1}^nf\!\left(\frac{2k-1}{2n}\right)-\int_0^1f(x)\,dx\right\}
  \]
  を $f'(0)$，$f'(1)$ を用いて表せ．
  \item 極限 $\displaystyle\lim_{n\to\infty}n^2\left(\sum_{k=1}^n\frac{4n}{4n^2+(2k-1)^2}-\frac\pi4\right)$ を求めよ．
\end{enumerate}

次の無限級数の和を求めよ．
\begin{enumerate}
  \item $\displaystyle\sum_{n=0}^\infty\left(\frac12\right)^n\cos^3\frac{n\pi}6$
  \item $\displaystyle\sum_{n=1}^\infty n\left(\frac12\right)^n\cos\frac{n\pi}3$ \quad および \quad $\displaystyle\sum_{n=1}^\infty n\left(\frac12\right)^n\sin\frac{n\pi}3$
\end{enumerate}

$f(x)=2x+1,\ g(x)=x^2-3$ とする．\begin{enumerate}
  \item 合成関数 $(g\circ f)(x)$ を求めよ．
  \item 合成関数 $(f\circ g)(x)$ を求めよ．
\end{enumerate}

次の極限を求めよ．\begin{enumerate}
  \item $\displaystyle\lim_{n\to\infty}\frac{3n^2-n+4}{2n^2+5}$
  \item $\displaystyle\lim_{n\to\infty}\frac{2n+1}{\sqrt{n^2+3n}}$
\end{enumerate}

次の極限を求めよ．\begin{enumerate}
  \item $\displaystyle\lim_{n\to\infty}\frac{3^{n+1}+2^n}{3^n-2^{n+1}}$
  \item $\displaystyle\lim_{n\to\infty}\frac{4^n-1}{5^n+1}$
\end{enumerate}

無限等比級数 $1+(x-1)+(x-1)^2+(x-1)^3+\cdots$ について．\begin{enumerate}
  \item この級数が収束するような $x$ の値の範囲を求めよ．
  \item (1) のとき，和を $x$ の式で表せ．
\end{enumerate}

次の循環小数を分数で表せ．\begin{enumerate}
  \item $0.\dot{2}\dot{7}$
  \item $0.1\dot{2}\dot{5}$
\end{enumerate}

次の極限を求めよ．\begin{enumerate}
  \item $\displaystyle\lim_{x\to2}\frac{x^2-4}{x^2-3x+2}$
  \item $\displaystyle\lim_{x\to1}\frac{\sqrt{x+3}-2}{x-1}$
\end{enumerate}

次の極限を求めよ．\begin{enumerate}
  \item $\displaystyle\lim_{x\to0}\frac{\sin3x}{x}$
  \item $\displaystyle\lim_{x\to0}\frac{1-\cos x}{x^2}$
\end{enumerate}

次の極限を求めよ．\begin{enumerate}
  \item $\displaystyle\lim_{x\to\infty}\left(1+\frac2x\right)^x$
  \item $\displaystyle\lim_{x\to0}\frac{e^{2x}-1}{x}$
\end{enumerate}

$a_1=1,\ a_{n+1}=\dfrac12a_n+3\ (n=1,2,3,\ldots)$ で定まる数列 $\{a_n\}$ について．\begin{enumerate}
  \item 一般項 $a_n$ を求めよ．
  \item $\displaystyle\lim_{n\to\infty}a_n$ を求めよ．
\end{enumerate}

次の極限を求めよ．\begin{enumerate}
  \item $\displaystyle\lim_{x\to0}\frac{1-\cos2x}{x\sin x}$
  \item $\displaystyle\lim_{x\to\pi}\frac{\sin x}{x-\pi}$
\end{enumerate}

$a_1=1,\ a_{n+1}=\dfrac{a_n}{2a_n+1}\ (n=1,2,3,\ldots)$ で定まる数列 $\{a_n\}$ がある．\begin{enumerate}
  \item $b_n=\dfrac1{a_n}$ とおくとき，$b_n$ を $n$ の式で表せ．
  \item $\displaystyle\lim_{n\to\infty}na_n$ を求めよ．
\end{enumerate}

無限級数 $\displaystyle\sum_{n=1}^{\infty}\frac{1}{n(n+1)(n+2)}$ について．\begin{enumerate}
  \item 第 $n$ 項までの部分和 $S_n$ を求めよ．
  \item この無限級数の和を求めよ．
\end{enumerate}

無限級数 $1-\dfrac12+\dfrac12-\dfrac13+\dfrac13-\dfrac14+\cdots$ の第 $n$ 項までの部分和を $S_n$ とする．\begin{enumerate}
  \item $S_{2n-1}$ を求めよ．
  \item $S_{2n}$ を $n$ の式で表せ．
  \item この無限級数の和を求めよ．
\end{enumerate}

次の極限を求めよ．\begin{enumerate}
  \item $\displaystyle\lim_{x\to-\infty}\left(\sqrt{x^2+2x}+x\right)$
  \item $\displaystyle\lim_{x\to1+0}\frac{x^2-x}{|x-1|}$ と $\displaystyle\lim_{x\to1-0}\frac{x^2-x}{|x-1|}$
\end{enumerate}

次の極限を求めよ．\begin{enumerate}
  \item $\displaystyle\lim_{x\to0}\frac{\log(1+3x)}{x}$
  \item $\displaystyle\lim_{n\to\infty}\left(1-\frac1n\right)^{2n}$
\end{enumerate}

実数 $x$ に対し，$x$ を超えない最大の整数を $[x]$ で表す．次の極限を求めよ．\begin{enumerate}
  \item $\displaystyle\lim_{x\to\infty}\frac{[2x]}{x}$
  \item $\displaystyle\lim_{n\to\infty}\left(2^n+3^n\right)^{\frac1n}$
\end{enumerate}

無限級数 $x+x(1-x)+x(1-x)^2+\cdots+x(1-x)^{n-1}+\cdots$ について．\begin{enumerate}
  \item この無限級数が収束するような実数 $x$ の値の範囲を求めよ．
  \item $x\neq0$ で (1) の範囲にあるとき，和を求めよ．
\end{enumerate}

関数 $f(x)=x^2-2x+2\ (x\geqq1)$ について．\begin{enumerate}
  \item 逆関数 $f^{-1}(x)$ を求めよ．
  \item $y=f(x)$ のグラフと $y=f^{-1}(x)$ のグラフの共有点の座標をすべて求めよ．
\end{enumerate}

Oを原点とする $xyz$ 空間に点 $\mathrm P_k\left(\dfrac kn,\ 1-\dfrac kn,\ 0\right)$，$k=0,1,\dots,n$ をとる．また，$z$ 軸上 $z\geqq0$ の部分に，点 $\mathrm Q_k$ を線分 $\mathrm P_k\mathrm Q_k$ の長さが1になるようにとる．三角形 $\mathrm Q_k\mathrm P_k\mathrm P_{k+1}$ の面積を $S_k$ とする．
\begin{enumerate}
  \item $S_k$ を $n$，$k$ で表せ．
  \item 極限 $\displaystyle\lim_{n\to\infty}\sum_{k=0}^{n-1}S_k$ を求めよ．
\end{enumerate}

$a$ を1より大きい定数とし，曲線 $y=\log x$，$x$ 軸，直線 $x=a$ で囲まれた部分の面積を $S_1$ とする．$1\leqq b\leqq a$ をみたす $b$ に対し，曲線 $y=\log x$ 上の点 $(b,\log b)$ における接線を $\ell_b$ とし，$\ell_b$，$x$ 軸，2直線 $x=1,\ x=a$ で囲まれた台形の面積を $T(b)$ とする．
\begin{enumerate}
  \item $T(b)$ を最小にする $b$ の値と，その最小値 $S_3$ を求めよ．
  \item $\displaystyle\lim_{a\to\infty}\frac{S_3-S_1}{a}$ を求めよ．
  \item $\displaystyle\lim_{a\to1+0}\frac{S_3-S_1}{(a-1)^3}$ を求めよ．
\end{enumerate}

$n$ を3以上の整数とする．
\begin{enumerate}
  \item $x$ についての方程式 $e^x=x^n$ はちょうど2つの正の実数解をもつことを示せ．また，その小さい方を $\alpha_n$ とするとき，$1<\alpha_n<e$ であることを示せ．
  \item 極限 $\displaystyle\lim_{n\to\infty}n(\alpha_n-1)$ および $\displaystyle\lim_{n\to\infty}{\alpha_n}^n$ を求めよ．
  \item 極限 $\displaystyle\lim_{n\to\infty}n\bigl\{n(\alpha_n-1)-1\bigr\}$ を求めよ．
\end{enumerate}

白球と赤球の入った袋から2個の球を同時に取り出すゲームを考える．取り出した2球がともに白球ならば「成功」でゲームを終了し，そうでないときは「失敗」とし，取り出した2球に赤球を1個加えた3個の球を袋にもどしてゲームを続ける．最初に白球が2個，赤球が2個袋に入っているとし，ちょうど $n$ 回目に成功する（$n-1$ 回目まで失敗し $n$ 回目に成功する）確率を $p_n$ とする．
\begin{enumerate}
  \item $p_n$ を求めよ．
  \item $\displaystyle\lim_{N\to\infty}\sum_{n=1}^{N}p_n$ を求めよ．
  \item $\displaystyle\lim_{M\to\infty}\sum_{m=1}^{M}p_{2m}$ を求めよ．
\end{enumerate}

$a,m$ は自然数で，$a$ は定数とする．$xy$ 平面上の点 $(m,a)$ を頂点とし，原点と点 $(2m,0)$ を通る放物線を考える．この放物線と $x$ 軸で囲まれる領域の面積を $S_m$，この領域の内部および境界線上にある格子点の数を $L_m$ とする．
\begin{enumerate}
  \item 極限値 $\displaystyle c(a)=\lim_{m\to\infty}\frac{L_m}{S_m}$ を $a$ を用いて表せ．
  \item $\displaystyle\lim_{a\to\infty}c(a)$ を求めよ．
\end{enumerate}

$n$ を2以上の整数とする．$n$ 個のボールを $n^2$ 個の箱へ投げ入れる．各ボールはいずれかの箱に入り，どの箱に入る確率も等しく，各ボールの入り方は互いに独立であるとする．
\begin{enumerate}
  \item どの箱にも1個以下のボールしか入っていない確率を $p_n$ とする．$\displaystyle\lim_{n\to\infty}p_n$ を求めよ．
  \item ちょうど1つの箱に2個のボールが入り，他のどの箱にも1個以下しか入っていない確率を $r_n$ とする．$\displaystyle\lim_{n\to\infty}r_n$ を求めよ．
\end{enumerate}

$n=0,1,2,\dots$ に対して $\displaystyle a_n=\int_0^1x^n\sin\pi x\,dx$ とおく．
\begin{enumerate}
  \item $a_n$ と $a_{n+2}$ の関係式を求めよ．
  \item $\displaystyle\lim_{n\to\infty}n^2a_n$ を求めよ．
  \item $\displaystyle\lim_{n\to\infty}n\left(\pi-n^2a_n\right)$ を求めよ．
\end{enumerate}

$p$ を正の整数とし，$x$ に関する2次方程式 $x^2-px-1=0$ の2つの解を $\alpha$，$\beta$（$\alpha>\beta$）とする．$L_n=\alpha^n+\beta^n$，$x_n=(-\alpha)^n\sin(\alpha^n\pi)$（$n=0,1,2,\dots$）とおく．
\begin{enumerate}
  \item すべての $n$ について $L_n$ は整数であることを示せ．また，$L_n$ が偶数となるための $n$ の条件を，$p$ が偶数の場合と奇数の場合に分けて求めよ．
  \item 極限 $\displaystyle\lim_{n\to\infty}x_n$ が存在するための $p$ の条件と，そのときの極限値を求めよ．
  \item $p$ が奇数のとき，$\displaystyle\lim_{m\to\infty}x_{3m}$，$\displaystyle\lim_{m\to\infty}x_{3m+1}$，$\displaystyle\lim_{m\to\infty}x_{3m+2}$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $a$ を実数とする．点 $(a,0)$ を通り曲線 $y=e^x+1$ に接する直線はただ1つ存在し，その接点の $x$ 座標 $t$ は $t>a+1$ をみたすことを示せ．
  \item $a_1=0$ とし，$n=1,2,\dots$ に対して，点 $(a_n,0)$ を通り $y=e^x+1$ に接する直線の接点の $x$ 座標を $a_{n+1}$ とする．$\displaystyle\lim_{n\to\infty}e^{a_n}(a_{n+1}-a_n-1)$ を求めよ．
  \item (2) の数列について，$\displaystyle\lim_{n\to\infty}(a_{n+1}-a_n-1)^{\frac1n}$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $\displaystyle\lim_{n\to\infty}\int_0^2(1+x^n)^{\frac1n}\,dx$ を求めよ．
  \item $a$ を正の実数とし，$M=\max\{1,a\}$ とする．$\displaystyle\lim_{n\to\infty}n\left\{(1+a^n)^{\frac1n}-M\right\}$ を求めよ．
\end{enumerate}

$n$ を3以上の自然数とする．平面上に，点 O を中心とする半径1の円 $C$ がある．$C$ に外接する半径が等しい $n$ 個の円 $K_1,\ K_2,\ \cdots,\ K_n$ が，この順に輪をなし，隣り合う2円（$K_n$ と $K_1$ も隣り合うとする）がすべて互いに外接しているとする．この半径を $R_n$ とし，O を中心とし $K_1,\ \cdots,\ K_n$ のすべてに内接する円を $\Gamma_n$ とする．

$\Gamma_n$ の内部にあって，$C$ の外部にあり，どの $K_i$ の内部にもない部分は $2n$ 個の部分に分かれる．そのうち $C$ と隣り合う2円で囲まれた $n$ 個の部分の面積の和を $T_n$，$\Gamma_n$ と隣り合う2円で囲まれた $n$ 個の部分の面積の和を $U_n$ とし，$G_n=T_n+U_n$ とおく．
\begin{enumerate}
  \item $\displaystyle\lim_{n\to\infty}nG_n$ を求めよ．
  \item $\displaystyle\lim_{n\to\infty}n^2(U_n-T_n)$ を求めよ．
\end{enumerate}

$k$ を $-2<k<2$ をみたす定数とすると，$x$ の方程式 $x^3-3x-k=0$ は異なる3つの実数解をもつ．それらを $\alpha,\ \beta,\ \gamma$（$\gamma<\beta<\alpha$）とする．
\begin{enumerate}
  \item $\displaystyle\lim_{k\to2-0}\frac{\beta+1}{\sqrt{2-k}}$ を求めよ．
  \item $\displaystyle\lim_{k\to2-0}\frac{(\beta-\gamma)^2}{2-k}$ を求めよ．
  \item (2) の極限値を $L$ とするとき，$\displaystyle\lim_{k\to2-0}\frac1{2-k}\left\{\frac{(\beta-\gamma)^2}{2-k}-L\right\}$ を求めよ．
\end{enumerate}

$a,b,c,d$ を正の定数とし，$f(x)=x^4+ax^3+bx^2+cx+d$ とおく．
\begin{enumerate}
  \item 次をみたす定数 $p,q$ が存在することを示し，$p,q$ を $a,b$ で表せ．
  \begin{center}
  ある定数 $X\geqq1$，$L>0$ があって，$x\geqq X$ ならば $\left|\sqrt{f(x)}-(x^2+px+q)\right|\leqq\dfrac Lx$
  \end{center}
  \item すべての自然数 $n$ に対して $\sqrt{f(n)}$ が自然数であるとする．このとき，自然数 $m,k$ を用いて $f(x)=(x^2+mx+k)^2$ と表されることを示せ．
  \item (2) の仮定の「すべての自然数 $n$」を「すべての正の偶数 $n$」に置きかえると，(2) の結論は成り立たないことを示せ．
\end{enumerate}

2人のプレーヤー A，B が対戦を繰り返す．1回の対戦で A が勝つ確率は $p$，B が勝つ確率は $q$，引き分けになる確率は $r$ である（$p>0$，$q>0$，$r>0$，$p+q+r=1$）．A と B は初めにそれぞれ2枚の金貨を持っている．1回の対戦につき，勝者は敗者から1枚の金貨を受け取り，引き分けのときは金貨は移動しない．一方のプレーヤーがすべての金貨を手に入れたとき，ゲームを終了する．ちょうど $n$ 回目の対戦で A がすべての金貨を手に入れる確率を $P_n$ とする．また $s=\sqrt{2pq}$ とおく．
\begin{enumerate}
  \item $P_n=\dfrac{p^2}{2s}\left\{(r+s)^{n-1}-(r-s)^{n-1}\right\}$（$n=1,2,3,\cdots$）であることを示せ．
  \item A が最終的にすべての金貨を手に入れる確率 $S=\displaystyle\sum_{n=1}^{\infty}P_n$ を $p,q$ で表せ．
  \item $S$ と $\dfrac p{p+q}$ の大小を調べよ．
\end{enumerate}

関数 $f(x)=x+e^x$ は実数全体で定義された増加関数で，その逆関数を $g(x)$ とする（$g(x)$ も実数全体で定義され，微分可能である）．
\begin{enumerate}
  \item $x>1$ のとき $\log(x-\log x)<g(x)<\log x$ が成り立つことを示し，$\displaystyle\lim_{x\to\infty}\{g(x)-\log x\}$ を求めよ．
  \item $\displaystyle\lim_{n\to\infty}n\{g(n+1)-g(n)\}$ を求めよ．
  \item $\displaystyle\lim_{n\to\infty}\frac{n^2}{\log n}\left\{g(n+1)-g(n)-\frac1n\right\}$ を求めよ．
\end{enumerate}

$n$ を2以上の整数とする．$xy$ 平面上に定点 A$(1,0)$ がある．$y$ 軸上の点 P を通り $x$ 軸に平行な直線上で，$\mathrm{AP}+2\,\mathrm{PQ}\leqq n$ をみたす点 Q を考える．P が $y$ 軸上を動くとき，Q の存在範囲を $D(n)$ とする．ただし，対数は自然対数とする．
\begin{enumerate}
  \item $D(n)$ を $x$，$y$ の不等式で表せ．また，$D(n)$ の面積 $T(n)$ を求めよ．
  \item $x$ 座標と $y$ 座標がともに整数である点を格子点という．$D(n)$ に含まれる格子点の個数 $S(n)$ を $n$ で表せ．
  \item 極限 $\displaystyle\lim_{n\to\infty}\bigl\{S(n)-T(n)+n-\log n\bigr\}$ を求めよ．
\end{enumerate}

$n$ を正の整数とする．1から $n$ までの番号のついた $n$ 個の箱があり，どの箱にも $n$ 本のくじが入っている．番号 $l$ の箱には当たりくじがちょうど $l$ 本入っている．次の試行を行う．
\begin{itemize}
  \item[\textcircled{\scriptsize 1}] 箱を1つ選ぶ．ただし，番号 $l$ の箱を選ぶ確率は $\dfrac{2l}{n(n+1)}$ とする（$l=1,2,\dots,n$）．
  \item[\textcircled{\scriptsize 2}] \textcircled{\scriptsize 1} で選んだ箱から，くじを1本引いては元に戻すことを繰り返す．
\end{itemize}
正の整数 $m$ と $0\leqq k\leqq m$ をみたす整数 $k$ に対し，\textcircled{\scriptsize 2} で最初の $m$ 回のうち当たりがちょうど $k$ 回である確率を $p_n(m,k)$ とする．
\begin{enumerate}
  \item 0以上の整数 $a$，$b$ に対し $I(a,b)=\displaystyle\int_0^1x^a(1-x)^b\,dx$ とおく．$I(a,b)=\dfrac{a!\,b!}{(a+b+1)!}$ であることを示せ．
  \item $\displaystyle\lim_{n\to\infty}p_n(m,k)$ を $m$，$k$ で表せ．
  \item 最初の $m$ 回がすべて当たりであったという条件のもとで，$m+1$ 回目も当たりである条件付き確率を $q_n(m)$ とする．$\displaystyle\lim_{n\to\infty}q_n(m)$ を求めよ．また，この極限値が $0.99$ 以上となる最小の $m$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 実数 $a$ に対し，極限 $\displaystyle\lim_{x\to+0}\int_x^1t^a\,dt$ を調べよ．
  \item $a<-1$ とする．極限 $\displaystyle\lim_{x\to+0}x^{-a-1}\int_x^1t^ae^t\,dt$ を求めよ．
  \item 極限 $\displaystyle\lim_{x\to+0}\frac{1}{\log x}\left(\int_x^1\frac{e^t}{t^2}\,dt-\frac1x\right)$ を求めよ．
\end{enumerate}

関数 $y=\dfrac1x$（$x>0$）のグラフを $C$ とし，$n=1,2,3,\dots$ に対して $C$ 上の点 $\mathrm A_n\left(n,\dfrac1n\right)$ における $C$ の接線を $\ell_n$ とする．
\begin{enumerate}
  \item $\ell_n$ と $\ell_{n+1}$ の交点 $\mathrm P_n$ の座標を求めよ．
  \item 三角形 $\mathrm A_n\mathrm P_n\mathrm A_{n+1}$ の面積 $S_n$ を求めよ．
  \item 無限級数 $\displaystyle\sum_{n=1}^\infty S_n$ の和を求めよ．
\end{enumerate}
